const get = <Z extends z.ZodTypeAny>(
  url: string,
  schema: Z,
  options?: Options,
): ResultAsync<z.infer<Z>, HTTPError | ZodError> => {
  return fromPromise(
    captain.get(url, options).json(),
    (e) => e as HTTPError,
  ).andThen(tryParse(schema));
};

